import json,sys
d=json.load(open(sys.argv[1]))
print(d['description'])
for c in d['customers']:
    s=c['services']
    print('='*30, c['customerNo'], c['firstName'], c['lastName'])
    cl=s.get('cards.list',{})
    print(' list http', cl.get('http'), 'cards:', [(x['cardNumber'],x['productName'],x.get('isMainCard'),x.get('status')) for x in (cl.get('response',{}).get('data',{}) or {}).get('cards',[])] if cl.get('http')==200 else cl.get('response',{}).get('result',{}).get('code'))
    for cn,b in (s.get('cards.balance') or {}).items():
        r=b['response']; dd=r.get('data')
        extra = {k:v for k,v in b.items() if k not in ('http','response')}
        if not dd:
            print('  bal',cn,b['http'],r['result']['code'],extra); continue
        def blk(k):
            x=dd.get(k)
            if x is None: return 'MISSING'
            return f"{x.get('statementPaymentStatus')} sd={x.get('statementDebt')} min={x.get('minPayment')} rd={x.get('remainingDebt')} rmin={x.get('remainingMinPayment')} tot={x.get('totalDebt')} tr={x.get('transferAmount')} rauto={x.get('remainAutomaticPaymentAmount')}"
        print('  bal',cn,b['http'],extra,'sd',dd.get('statementDate'),'due',dd.get('lastPayDate'),'next',dd.get('nextStatementDate'),dd.get('nextLastPayDate'),'top',dd.get('statementPaymentStatus'),dd.get('totalDebtPaymentStatus'),'auto',dd.get('automaticPaymentFlag'),'name',repr(dd.get('productName')))
        for k in ('debtTL','debtUSD','debtEUR','debtGBP'):
            print('     ',k,blk(k))
    for cn,b in (s.get('statement.week.get') or {}).items():
        r=b['response']; dd=r.get('data')
        if not dd: print('  wk',cn,b['http'],r['result']['code']); continue
        print('  wk',cn,'week',dd.get('statementWeek'),'day',dd.get('statementDay'),'next',dd.get('nextStatementDate'),dd.get('nextLastPayDate'),'rel',repr(dd.get('relationType')),dd.get('relatedCardNumber'),dd.get('relatedCardProductName'))
    for cn,ws in (s.get('statement.week.decide') or {}).items():
        for w,b in ws.items():
            r=b['response']; dd=r.get('data')
            print('  dec',cn,w,b['http'], (dd.get('statementDate'),dd.get('statementDueDate'),dd.get('statementDay')) if dd else r['result']['code'])
    for cn,ws in (s.get('statement.week.change') or {}).items():
        for w,b in ws.items():
            r=b['response']; dd=r.get('data')
            extra = {k:v for k,v in b.items() if k not in ('http','response')}
            print('  chg',cn,w,b['http'],extra, (dd.get('exitState'),dd.get('responseCode'),dd.get('statementWeek')) if dd else r['result']['code'])
    e=s.get('contact.email.get')
    if e:
        r=e['response']; dd=r.get('data')
        print('  email',e['http'], (dd.get('communicationType'),dd.get('ibanEmail'),dd.get('ttsEmail')) if dd else r['result']['code'])
    p=s.get('statement.pdf.send')
    if p:
        r=p['response']; dd=p['response'].get('data')
        extra = {k:v for k,v in p.items() if k not in ('http','response')}
        print('  pdf',p['http'],extra, dd if dd else r['result']['code'])
    else:
        print('  pdf: NO ENTRY')
    other=set(s)-{'cards.list','cards.balance','statement.week.get','statement.week.decide','statement.week.change','contact.email.get','statement.pdf.send'}
    if other: print('  OTHER',other)
